3. **Availability Calculation**
```python
# Generate available slots for a service on a specific date
def generate_available_slots(service_id, date):
    service = Service.objects.get(id=service_id)
    if not service.is_valid_booking_date(date):
        return []

    # Get service hours
    service_hours = get_service_hours(service_id, date)
    if not service_hours:
        return []

    start_time, end_time = service_hours

    # Get all breaks
    breaks = get_service_breaks(service_id, date)

    # Calculate available slots
    current_time = datetime.combine(date, start_time)
    end_datetime = datetime.combine(date, end_time)

    available_slots = []

    while current_time + timedelta(minutes=service.duration_minutes) <= end_datetime:
        slot_start = current_time.time()
        slot_end = (current_time + timedelta(minutes=service.duration_minutes)).time()

        # Check if this slot overlaps with any break
        is_break_time = False
        for br in breaks:
            if (slot_start < br.end_time and slot_end > br.start_time):
                is_break_time = True
                break

        if not is_break_time:
            # Check if slot is available
            if is_slot_available(service_id, date, slot_start):
                available_slots.append((slot_start, slot_end))

        # Move to next possible slot
        current_time += timedelta(minutes=service.duration_minutes + service.break_minutes)

    return available_slots
```

