# Transactional booking to prevent overbooking
@transaction.atomic
def book_appointment(user_id, service_id, date, start_time, num_clients):
    # Lock the availability row
    availability = Availability.objects.select_for_update().get(
        service_id=service_id,
        date=date,
        start_time=start_time
    )

    # Check availability
    if availability.available_spots < num_clients:
        raise ValidationError("Not enough available spots.")

    # Create appointment
    appointment = Appointment.objects.create(
        user_id=user_id,
        availability_id=availability.id,
        number_of_clients=num_clients
    )

    # Update available spots
    availability.available_spots -= num_clients
    availability.save(update_fields=['available_spots'])

    return appointment
