var float spl_low_candidate = na

// Initialize on first bar
if bar_index == 0
    sp_anchor_index := bar_index
    sp_anchor_high := high
    sp_anchor_low := low
    sph_high_candidate := high
    spl_low_candidate := low

// Track current SPH/SPL values
var float temp_small_pivot_high = na
var float perm_small_pivot_high = na
var float temp_small_pivot_low = na
var float perm_small_pivot_low = na
var int last_sph_index = na
var int last_spl_index = na

// === SPH Detection Logic ===
if looking_for_sph and !na(sp_anchor_high)
    // Track the highest high since the anchor bar
    if high > sph_high_candidate
        sph_high_candidate := high

    // Count qualifying bars (lower high and lower close than anchor)
    if high < sp_anchor_high and close < sp_anchor_low
        sph_count += 1

    // Confirm SPH when two qualifying bars are found (non-consecutive allowed)
    if sph_count >= 2
        // Mark as temporary SPH
        temp_small_pivot_high := sph_high_candidate
        last_sph_index := bar_index

        // Reset for next pivot type (SPL)
        looking_for_sph := false
        looking_for_spl := true
        sp_anchor_index := bar_index
        sp_anchor_high := high
        sp_anchor_low := low
        sph_count := 0
        sph_high_candidate := na

// === SPL Detection Logic ===
if looking_for_spl and !na(sp_anchor_low)
    // Track the lowest low since the anchor bar
    if low < spl_low_candidate
        spl_low_candidate := low

    // Count qualifying bars (higher high and higher close than anchor)
    if high > sp_anchor_high and close > sp_anchor_low
        spl_count += 1

    // Confirm SPL when two qualifying bars are found (non-consecutive allowed)
    if spl_count >= 2
        // Mark as temporary SPL
        temp_small_pivot_low := spl_low_candidate
        last_spl_index := bar_index

        // Reset for next pivot type (SPH)
        looking_for_sph := true
        looking_for_spl := false
        sp_anchor_index := bar_index
        sp_anchor_high := high
        sp_anchor_low := low
        spl_count := 0
        spl_low_candidate := na

// === Convert temporary pivots to permanent when next pivot is confirmed ===
if !na(temp_small_pivot_high) and !na(perm_small_pivot_low)
    perm_small_pivot_high := temp_small_pivot_high
    temp_small_pivot_high := na
else if !na(temp_small_pivot_high) and bar_index > 100 and na(perm_small_pivot_high)
    // If no pivot confirmed after many bars, reset
    temp_small_pivot_high := na
    looking_for_sph := true
    looking_for_spl := false

if !na(temp_small_pivot_low) and !na(perm_small_pivot_high)
    perm_small_pivot_low := temp_small_pivot_low
    temp_small_pivot_low := na
else if !na(temp_small_pivot_low) and bar_index > 100 and na(perm_small_pivot_low)
    // If no pivot confirmed after many bars, reset
    temp_small_pivot_low := na
    looking_for_sph := false
    looking_for_spl := true

// Store confirmed SPH/SPL in arrays
var array<float> sph_array = array.new_float()
var array<int> sph_index_array = array.new_int()
var array<float> spl_array = array.new_float()
var array<int> spl_index_array = array.new_int()

if !na(perm_small_pivot_high)
    array.push(sph_array, perm_small_pivot_high)
    array.push(sph_index_array, last_sph_index)

if !na(perm_small_pivot_low)
