        System.out.println("In terms of hexadecimal notation, the S-box is given by: ");
        System.out.println("input  | 0 | 1 | 2 | 3 | 4 | 5 | 6 | 7");
        System.out.println("--------------------------------------");
        System.out.println("output | 6 | 5 | 1 | 0 | 3 | 2 | 7 | 4");

        // Compute LAT and normalize it (NLAT)
        int[][] nlatTable = new int[8][8];

        for (int a = 0; a < 8; a++) {
            for (int b = 0; b < 8; b++) {
                int latValue = lat(inputVectors, outputVectors, a, b);
                nlatTable[a][b] = latValue - 4;  // Normalize
            }
        }

        try {
            validateNLAT(nlatTable, expectedOutput);
            System.out.println("✅ All entries match the expected output.");
        } catch (ValidationException e) {
