            for (int val : row) {
                System.out.print(val + "\t");
            }
            System.out.println();
        }
    }

    /**
     * Compute the Linear Approximation Table (LAT) entry for mask pair (a, b)
     */
    public static int lat(int[][] input, int[][] output, int a, int b) {
        int count = 0;

        for (int x = 0; x < 8; x++) {
            // Compute input parity (a_parity)
            int aParity = 0;
            for (int i = 0; i < 3; i++) {
                if ((a >> (2 - i) & 1) == 1) {
                    aParity ^= input[x][i];
                }
            }

            // Compute output parity (b_parity)
            int bParity = 0;
            for (int j = 0; j < 3; j++) {
                if ((b >> (2 - j) & 1) == 1) {
                    bParity ^= output[x][j];
                }
            }

            if (aParity == bParity) {
                count++;
            }
        }
        return count;
    }

    /**
     * Validate computed NLAT against expected values
     * @throws ValidationException on first mismatch
     */
    private static void validateNLAT(int[][] computed, int[][] expected) throws ValidationException {
        for (int a = 0; a < 8; a++) {
            for (int b = 0; b < 8; b++) {
                if (computed[a][b] != expected[a][b]) {
                    throw new ValidationException(
                        String.format("Mismatch at a=%d, b=%d: computed %d, expected %d",
                                     a, b, computed[a][b], expected[a][b])
                    );
                }
            }
        }
    }

    /**
     * Custom exception for LAT validation failures
     */
    private static class ValidationException extends Exception {
        public ValidationException(String message) {
            super(message);
        }
    }
}
