import java.text.DecimalFormat;
import java.util.Random;
import java.util.Scanner;

public class DiceRollSimulator {
    public static void main(String[] args) {
        // Precompute theoretical probabilities based on possible dice combinations
        int[] sumCounts = {0, 0, 1, 2, 3, 4, 5, 6, 5, 4, 3, 2, 1}; // indexes 0-12, sums 2-12 used
        double[] theoretical = new double[13];
        for (int i = 2; i <= 12; i++) {
            theoretical[i] = (double) sumCounts[i] / 36.0;
        }

        DecimalFormat df = new DecimalFormat("#.####");
        Random rand = new Random();
        Scanner scanner = new Scanner(System.in);

        // Prompt user for number of simulations
        System.out.print("Enter the number of simulations to run: ");
        int numSimulations = scanner.nextInt();
        int[] simulations = new int[numSimulations];

        // Prompt user for number of rolls for each simulation
        for (int i = 0; i < numSimulations; i++) {
            System.out.print("Enter number of rolls for simulation " + (i + 1) + ": ");
            simulations[i] = scanner.nextInt();
        }

        // Print theoretical distribution with comments
        System.out.println("\nTheoretical Probability Distribution");
        System.out.println("X\tP(X)");
        System.out.println("-------------------");
        for (int x = 2; x <= 12; x++) {
            System.out.println(x + "\t" + df.format(theoretical[x]));
        }

        // Run simulations and display results
        for (int numRolls : simulations) {
            int[] counts = new int[13]; // To store counts for sums 2-12

            // Simulate dice rolls
            for (int i = 0; i < numRolls; i++) {
                int die1 = 1 + rand.nextInt(6);
                int die2 = 1 + rand.nextInt(6);
                int sum = die1 + die2;
                counts[sum]++;
            }

            // Print simulation results in tabular format
            System.out.println("\nSimulation of " + numRolls + " rolls:");
            System.out.println("X\tCount\tEm Prob\tP(X)");
            System.out.println("--------------------------------------------------");

            for (int x = 2; x <= 12; x++) {
                double emProb = (double) counts[x] / numRolls;
                String emStr = df.format(emProb);
                String tStr = df.format(theoretical[x]);

                // Format X and Count
                System.out.print(x + "\t" + counts[x]);

                // Adjust tabs after Count based on its length
                if (counts[x] < 10) {
                    System.out.print("\t\t\t"); // 3 tabs for single-digit counts
                } else if (counts[x] < 100) {
                    System.out.print("\t\t"); // 2 tabs for 2-digit counts
                } else if (counts[x] < 1000) {
                    System.out.print("\t"); // 1 tab for 3-digit counts
                } else {
                    System.out.print("\t"); // 1 tab for larger counts
                }

                // Print probabilities
                System.out.println(emStr + "\t" + tStr);
            }
        }
    }
}

