### 🧠 JavaScript (Core Animation)

```javascript
const canvas = document.getElementById('waveformCanvas');
const ctx = canvas.getContext('2d');

// Resize canvas to match CSS size
function resizeCanvas() {
  canvas.width = canvas.offsetWidth;
  canvas.height = 32;
}
window.addEventListener('resize', resizeCanvas);
resizeCanvas();

let offset = 0;
const period = 100; // width of one full wave cycle (in pixels)

function drawWaveform() {
  // Clear canvas
  ctx.clearRect(0, 0, canvas.width, canvas.height);

  // Draw baseline
  ctx.beginPath();
  ctx.moveTo(0, 16);
  ctx.lineTo(canvas.width, 16);
  ctx.strokeStyle = '#f00';
  ctx.lineWidth = 1;
  ctx.stroke();

  // Draw triangle waveform
  ctx.beginPath();
  ctx.strokeStyle = '#00f';
  ctx.lineWidth = 2;

  for (let x = 0; x < canvas.width; x++) {
    const waveX = x + offset;
    const t = (waveX % period) / period;

    // Triangle waveform: 0 → 32 → 0
    const y = t < 0.5
      ? 2 * t * 32
      : 32 - 2 * (t - 0.5) * 32;

    if (x === 0) {
      ctx.moveTo(x, y);
    } else {
      ctx.lineTo(x, y);
    }
  }

  ctx.stroke();

  // Scroll leftward
  offset += 0.5;

  requestAnimationFrame(drawWaveform);
}

drawWaveform();
```

