        // Poll room status every second
        const checkRoomStatus = setInterval(() => {
            fetch(`/room-status/${currentRoom}`)
                .then(response => response.json())
                .then(data => {
                    if (data.success && data.room.gameStarted) {
                        document.getElementById('waitingMessage').remove();
                        startGame();
                        clearInterval(checkRoomStatus);
                    }
                });
