            <td>${player2Data.hitOpponent}</td>
            <td>${player2Data.mushrooms}</td>
            <td>${player2Data.hearts}</td>
        `;

        // Create hexbin visualizations
        const hexbinContainer = document.querySelector('.hexbin-container');
        hexbinContainer.innerHTML = '';

        // Create hexbins for each player stat
        [player1Data, player2Data].forEach((player, index) => {
            const stats = [
                {title: 'Score', value: player.score},
                {title: 'Health', value: player.health},
                {title: 'Hits', value: player.hits},
                {title: 'Mushrooms', value: player.mushrooms}
            ];

            stats.forEach(stat => {
                const hex = document.createElement('div');
                hex.className = 'hexbin';
                hex.title = `${player.name} - ${stat.title}: ${stat.value}`;
                hex.style.backgroundColor = index === 0 ? '#4CAF50' : '#2196F3';
                hex.textContent = stat.value;
                hexbinContainer.appendChild(hex);
