        // Place pawns
        for(int i = 0; i < 8; ++i) {
            board[1][i] = std::make_unique<Piece>(Piece{PieceType::PAWN, PlayerColor::BLACK});
            board[6][i] = std::make_unique<Piece>(Piece{PieceType::PAWN, PlayerColor::WHITE});
        }

        // Place rooks
        board[0][0] = std::make_unique<Piece>(Piece{PieceType::ROOK, PlayerColor::BLACK});
        board[0][7] = std::make_unique<Piece>(Piece{PieceType::ROOK, PlayerColor::BLACK});
        board[7][0] = std::make_unique<Piece>(Piece{PieceType::ROOK, PlayerColor::WHITE});
        board[7][7] = std::make_unique<Piece>(Piece{PieceType::ROOK, PlayerColor::WHITE});

        // Place knights
        board[0][1] = std::make_unique<Piece>(Piece{PieceType::KNIGHT, PlayerColor::BLACK});
        board[0][6] = std::make_unique<Piece>(Piece{PieceType::KNIGHT, PlayerColor::BLACK});
        board[7][1] = std::make_unique<Piece>(Piece{PieceType::KNIGHT, PlayerColor::WHITE});
        board[7][6] = std::make_unique<Piece>(Piece{PieceType::KNIGHT, PlayerColor::WHITE});

        // Place bishops
        board[0][2] = std::make_unique<Piece>(Piece{PieceType::BISHOP, PlayerColor::BLACK});
        board[0][5] = std::make_unique<Piece>(Piece{PieceType::BISHOP, PlayerColor::BLACK});
        board[7][2] = std::make_unique<Piece>(Piece{PieceType::BISHOP, PlayerColor::WHITE});
        board[7][5] = std::make_unique<Piece>(Piece{PieceType::BISHOP, PlayerColor::WHITE});

        // Place queens
        board[0][3] = std::make_unique<Piece>(Piece{PieceType::QUEEN, PlayerColor::BLACK});
        board[7][3] = std::make_unique<Piece>(Piece{PieceType::QUEEN, PlayerColor::WHITE});

        // Place kings
        board[0][4] = std::make_unique<Piece>(Piece{PieceType::KING, PlayerColor::BLACK});
        board[7][4] = std::make_unique<Piece>(Piece{PieceType::KING, PlayerColor::WHITE});
    }

    bool movePiece(int x1, int y1, int x2, int y2) {
        if(x1 == x2 && y1 == y2) return false;
        if(!board[y1][x1]) return false;

        // Simple move implementation
        board[y2][x2] = std::move(board[y1][x1]);
        if(board[y2][x2]) {
            board[y2][x2]->hasMoved = true;

            // Update player ratings when a king is captured
            if(board[y2][x2]->type == PieceType::KING) {
                Player* winner = (board[y2][x2]->color == PlayerColor::WHITE) ? &players[1] : &players[0];
                Player* loser = (board[y2][x2]->color == PlayerColor::WHITE) ? &players[0] : &players[1];

                winner->updateRating(true);
                loser->updateRating(false);
                saveRatings();
            }

            currentTurn = (currentTurn == PlayerColor::WHITE) ? 
                          PlayerColor::BLACK : PlayerColor::WHITE;
            return true;
        }
        return false;
    }

    void saveRatings() {
        json ratings;
        ratings[players[0].name] = {
            {"wins", players[0].wins},
            {"losses", players[0].losses},
            {"games_played", players[0].gamesPlayed}
        };
        ratings[players[1].name] = {
            {"wins", players[1].wins},
            {"losses", players[1].losses},
            {"games_played", players[1].gamesPlayed}
        };

        std::ofstream file("ratings.json");
        if(file.is_open()) {
            file << ratings.dump(2);
            file.close();
        }
    }

    void loadRatings() {
        std::ifstream file("ratings.json");
        if(file.is_open()) {
            json ratings = json::parse(file);

            // Try to match existing player names
            for(auto& player : players) {
                if(ratings.contains(player.name)) {
                    player.wins = ratings[player.name]["wins"];
                    player.losses = ratings[player.name]["losses"];
                    player.gamesPlayed = ratings[player.name]["games_played"];
                }
            }
            file.close();
        }
    }

    std::vector<std::vector<std::unique_ptr<Piece>>> board;
    Player players[2];
    PlayerColor currentTurn = PlayerColor::WHITE;
};

class ChessRenderer {
public:
    ChessRenderer(sf::RenderWindow& window) : window(window) {
        loadTextures();
    }

    void loadTextures() {
        // Load chess piece textures
        std::string pieces[] = {"pawn", "rook", "knight", "bishop", "queen", "king"};
        for(auto color : {"white", "black"}) {
            for(auto piece : pieces) {
                textures[color + std::string(1, toupper(piece[0])) + piece.substr(1)]
                    .loadFromFile("pieces/" + std::string(color) + "_" + piece + ".png");
            }
        }
    }

    void drawBoard() {
        for(int y = 0; y < 8; ++y) {
            for(int x = 0; x < 8; ++x) {
                sf::RectangleShape square(sf::Vector2f(80, 80));
                square.setPosition(x * 80, y * 80);
                square.setFillColor((x + y) % 2 ? sf::Color(240,217,181) : sf::Color(181,136,99));
                window.draw(square);
            }
        }
    }

    void drawPieces(const ChessGame& game) {
        for(int y = 0; y < 8; ++y) {
            for(int x = 0; x < 8; ++x) {
                if(game.board[y][x]) {
                    auto& piece = *game.board[y][x];
                    std::string color = (piece.color == PlayerColor::WHITE) ? "white" : "black";
                    std::string type = getPieceTypeString(piece.type);
                    piece.sprite.setTexture(textures[color + type]);
                    piece.sprite.setPosition(x * 80, y * 80);
                    window.draw(piece.sprite);
                }
            }
        }
    }

    void drawUI(const ChessGame& game, bool showSettings, bool showRating) {
        // Draw right panel
        sf::RectangleShape panel(sf::Vector2f(360, 640));
        panel.setFillColor(sf::Color(220, 220, 220));
        panel.setPosition(640, 0);
