        }

        sf::Text whitePlayer(game.players[0].name, font, 16);
        whitePlayer.setPosition(660, 20);
        whitePlayer.setFillColor(sf::Color::Black);
        window.draw(whitePlayer);

        sf::Text blackPlayer(game.players[1].name, font, 16);
        blackPlayer.setPosition(660, 50);
        blackPlayer.setFillColor(sf::Color::Black);
        window.draw(blackPlayer);

        sf::Text turnText("Turn: " + 
            std::string(game.currentTurn == PlayerColor::WHITE ? "White" : "Black"), font, 16);
        turnText.setPosition(660, 80);
        turnText.setFillColor(sf::Color::Black);
        window.draw(turnText);

        // Draw buttons
        drawButton("Start Game", sf::FloatRect(660, 120, 300, 30));
        drawButton("Player Rating", sf::FloatRect(660, 160, 300, 30));
        drawButton("Settings", sf::FloatRect(660, 200, 300, 30));

        // Draw settings panel
        if(showSettings) {
            sf::RectangleShape settingsPanel(sf::Vector2f(300, 200));
            settingsPanel.setFillColor(sf::Color::White);
            settingsPanel.setPosition(50, 50);
            window.draw(settingsPanel);

            sf::RectangleShape border(sf::Vector2f(300, 200));
            border.setOutlineThickness(2);
            border.setOutlineColor(sf::Color::Black);
            border.setFillColor(sf::Color::Transparent);
            border.setPosition(50, 50);
            window.draw(border);

            sf::Text settingsTitle("Player Settings", font, 18);
            settingsTitle.setPosition(60, 60);
            settingsTitle.setFillColor(sf::Color::Black);
            window.draw(settingsTitle);

            // Input fields
            sf::RectangleShape input1(sf::Vector2f(200, 30));
            input1.setFillColor(sf::Color(240,240,240));
            input1.setPosition(60, 100);
            window.draw(input1);

            sf::RectangleShape input2(sf::Vector2f(200, 30));
            input2.setFillColor(sf::Color(240,240,240));
            input2.setPosition(60, 150);
            window.draw(input2);

            sf::Text player1(game.players[0].name, font, 16);
            player1.setPosition(65, 105);
            player1.setFillColor(sf::Color::Black);
            window.draw(player1);

            sf::Text player2(game.players[1].name, font, 16);
            player2.setPosition(65, 155);
            player2.setFillColor(sf::Color::Black);
            window.draw(player2);
        }

        // Draw rating window
        if(showRating) {
            sf::RenderWindow ratingWindow(sf::VideoMode(400, 300), "Player Ratings");
            while(ratingWindow.isOpen()) {
