private:
    std::string getPieceTypeString(PieceType type) {
        switch(type) {
            case PieceType::PAWN: return "Pawn";
            case PieceType::ROOK: return "Rook";
            case PieceType::KNIGHT: return "Knight";
            case PieceType::BISHOP: return "Bishop";
            case PieceType::QUEEN: return "Queen";
            case PieceType::KING: return "King";
            default: return "";
        }
    }

    void drawButton(const std::string& text, const sf::FloatRect& rect) {
        sf::RectangleShape button(sf::Vector2f(rect.width, rect.height));
        button.setFillColor(sf::Color(150, 150, 150));
        button.setPosition(rect.left, rect.top);
        window.draw(button);

        sf::Text buttonText(text, font, 16);
        buttonText.setPosition(rect.left + 5, rect.top + 5);
        buttonText.setFillColor(sf::Color::Black);
        window.draw(buttonText);
    }

    sf::RenderWindow& window;
    std::map<std::string, sf::Texture> textures;
    sf::Font font;
};

class ChessController {
public:
    ChessController() : window(sf::VideoMode(1000, 640), "Chess Game") {
        game.players[0].name = "Player 1";
        game.players[1].name = "Player 2";
    }

    void run() {
        while(window.isOpen()) {
            processEvents();
            window.clear();
            renderer.drawBoard();
            renderer.drawPieces(game);
            renderer.drawUI(game, showSettings, showRating);
            window.display();
        }
    }

private:
    void processEvents() {
        sf::Event event;
        while(window.pollEvent(event)) {
            if(event.type == sf::Event::Closed)
                window.close();

            if(event.type == sf::Event::MouseButtonPressed) {
                handleMouseClick(event.mouseButton.x, event.mouseButton.y);
            }

            if(event.type == sf::Event::TextEntered) {
                // Handle text input for settings
            }
        }
    }

    void handleMouseClick(int x, int y) {
        // Handle board clicks
        if(x < 640 && y < 640) {
            int squareX = x / 80;
            int squareY = y / 80;

            if(selectedSquare.has_value()) {
                auto [fromX, fromY] = selectedSquare.value();
                game.movePiece(fromX, fromY, squareX, squareY);
                selectedSquare.reset();
            } else if(game.board[squareY][squareX]) {
                selectedSquare = std::make_pair(squareX, squareY);
            }
        }

        // Handle UI buttons
        else {
            // Start Game button
            if(x > 660 && x < 960 && y > 120 && y < 150) {
                game = ChessGame();
                selectedSquare.reset();
            }
            // Player Rating button
            else if(x > 660 && x < 960 && y > 160 && y < 190) {
                showRating = true;
            }
            // Settings button
            else if(x > 660 && x < 960 && y > 200 && y < 230) {
                showSettings = !showSettings;
            }
        }
    }

    sf::RenderWindow window;
    ChessGame game;
    ChessRenderer renderer{window};
    std::optional<std::pair<int, int>> selectedSquare;
    bool showSettings = false;
    bool showRating = false;
};

int main() {
    ChessController controller;
    controller.run();
    return 0;
}
