## ✅ 3. Define the Drawing Canvas with SVG

### 📁 `components/DrawingCanvas.js`

```javascript
import React, { useState, useEffect, useRef } from 'react';
import {
  View,
  Dimensions,
  StyleSheet,
  Text,
  Alert,
  PanResponder,
} from 'react-native';
import Svg, { Circle, Path, Text as SvgText } from 'react-native-svg';
import { fetchPoints } from '../services/api';

const { width, height } = Dimensions.get('window');

const DrawingCanvas = () => {
  const [points, setPoints] = useState([]);
  const [currentBatch, setCurrentBatch] = useState(0);
  const [lines, setLines] = useState([]);
  const [currentPath, setCurrentPath] = useState([]);
  const [loading, setLoading] = useState(true);
  const [error, setError] = useState(null);
  const batchSize = 10;
  const padding = 40;

  // Scale API coordinates (0–2160) to screen size
  const scalePoint = (point) => ({
    x: (point.x / 2160) * (width - 2 * padding) + padding,
    y: (point.y / 2160) * (height - 2 * padding) + padding,
  });

  // Load points from API
  useEffect(() => {
    const loadPoints = async () => {
      try {
        const data = await fetchPoints();
        setPoints(data);
        setLoading(false);
      } catch (err) {
        setError('Failed to load points');
        Alert.alert('Error', 'Failed to load points. Please check your connection.');
        setLoading(false);
      }
    };
    loadPoints();
  }, []);

  // Find closest point to touch within 50px radius
  const findClosestPoint = (x, y) => {
    const startIdx = currentBatch * batchSize;
    const endIdx = Math.min(startIdx + batchSize, points.length);
    let closest = null;
    let minDist = 2500; // 50px radius (50^2 = 2500)

    for (let i = startIdx; i < endIdx; i++) {
      const scaled = scalePoint(points[i]);
      const dx = scaled.x - x;
      const dy = scaled.y - y;
      const dist = dx * dx + dy * dy;

      if (dist < minDist) {
        minDist = dist;
        closest = scaled;
      }
    }

    return minDist < 2500 ? closest : null;
  };

  // Touch handling with PanResponder
  const panResponder = useRef(
    PanResponder.create({
      onStartShouldSetPanResponder: () => true,
      onPanResponderGrant: (evt, gestureState) => {
        const touchX = gestureState.x;
        const touchY = gestureState.y;
        const closest = findClosestPoint(touchX, touchY);

        if (closest) {
          setCurrentPath([closest.x, closest.y]);
        }
      },
      onPanResponderMove: (evt, gestureState) => {
        if (currentPath.length === 0) return;

        setCurrentPath(prev => [...prev, gestureState.x, gestureState.y]);
      },
      onPanResponderRelease: () => {
        if (currentPath.length > 0) {
          setLines(prev => [...prev, { points: [...currentPath] }]);
          setCurrentPath([]);
        }

        const nextBatchStart = (currentBatch + 1) * batchSize;
        if (nextBatchStart < points.length) {
          setCurrentBatch(prev => prev + 1);
        }
      },
    })
  ).current;

  if (loading) {
    return <Text style={styles.loading}>Loading points...</Text>;
  }

  if (error) {
    return <Text style={styles.error}>{error}</Text>;
  }

  const startIdx = currentBatch * batchSize;
  const currentPoints = points
    .slice(startIdx, startIdx + batchSize)
    .map(p => scalePoint(p));

  return (
    <View style={styles.container} {...panResponder.panHandlers}>
      <Svg style={styles.svg}>
        {/* Existing lines */}
        {lines.map((line, index) => (
          <Path
            key={`line-${index}`}
            d={`M ${line.points.join(' ')}`}
            stroke="blue"
            strokeWidth="2"
            fill="none"
          />
        ))}

        {/* Current path being drawn */}
        {currentPath.length > 0 && (
          <Path
            d={`M ${currentPath.join(' ')}`}
            stroke="blue"
            strokeWidth="2"
            fill="none"
          />
        )}

        {/* Current batch of points */}
        {currentPoints.map((point, index) => (
          <Circle
            key={`point-${startIdx + index}`}
            cx={point.x}
            cy={point.y}
            r={10}
            fill="red"
          />
        ))}

        {/* Point labels */}
        {currentPoints.map((point, index) => (
          <SvgText
            key={`label-${startIdx + index}`}
            x={point.x + 5}
            y={point.y + 5}
            fontSize="14"
            fill="black"
          >
            {startIdx + index + 1}
          </SvgText>
        ))}
      </Svg>
    </View>
  );
};

const styles = StyleSheet.create({
  container: {
    flex: 1,
    backgroundColor: 'white',
  },
  svg: {
    flex: 1,
  },
  loading: {
    flex: 1,
    textAlign: 'center',
    marginTop: 50,
  },
  error: {
    color: 'red',
    textAlign: 'center',
    margin: 20,
  },
});

export default DrawingCanvas;
```

