function perform_accuracy_check()
    % Perform accuracy check with different panel numbers
    panel_numbers = [10, 20, 40, 80, 160];
    max_errors = [];

    fprintf('Performing accuracy check with different panel numbers...\n');

    for n_panels = panel_numbers
        % Generate a circular cylinder with n_panels
        theta = linspace(0, 2*pi, n_panels+1);
        x = cos(theta);
        y = sin(theta);
        points = [x' y'];

        % Save to temporary file
