%% 2D Source-Vortex Panel Method for Lifting Flows
% Implements Kutta-Joukowski theorem with vortex panels
% Reads panel data from file
% Prompts user for flow conditions
% Computes pressure coefficients with comparison to analytical results
% Performs accuracy check with varying panel numbers

function source_vortex_panel_method()
    % Clear workspace and command window
    clc;
    clear all;
    close all;

    try
        % Display welcome message
        disp('=== 2D Source-Vortex Panel Method ===');
        disp('Analyzes lifting flows using source-vortex panels');
        disp('Includes Kutta condition and Cp validation');

        % Get panel file from user
        filename = input('Enter panel file name (e.g., flat_plate.txt): ', 's');

        % Read panel data
        [panels, points] = read_panels(filename);
        n_panels = size(panels, 1);
        fprintf('Number of panels: %d\n', n_panels);

        % Compute control points and geometry properties
        [midpoints, normals, panel_lengths, tangents] = compute_control_points(panels);

        % Get flow conditions from user with validation
        Vinf = get_validated_input('Enter free stream velocity (Vinf): ', ...
            @(x) x > 0, 'Velocity must be positive');
        alpha_deg = get_validated_input('Enter angle of attack (degrees): ', ...
            @(x) x >= -360 && x <= 360, 'Angle must be between -360 and 360');

        % Compute influence matrix
        A = compute_influence_matrix(midpoints, normals, panels, panel_lengths);

        % Compute RHS
        rhs = compute_rhs(alpha_deg, Vinf, normals);

        % Solve for source and vortex strengths
        solution = A \ rhs;
        sigma = solution(1:n_panels);
        gamma = solution(n_panels + 1);

        % Compute pressure coefficients
        [cp, theta, cp_analytical] = compute_pressure_coefficients(...
            Vinf, alpha_deg, sigma, gamma, panels, midpoints, normals, tangents, panel_lengths);

        % Plot geometry
        figure;
        plot(points(:,1), points(:,2), 'k-o', 'MarkerFaceColor', 'k');
        title('Panel Geometry');
        xlabel('x');
        ylabel('y');
        axis equal;
        grid on;

        % Compare with analytical solution if possible
        if ~isempty(theta)
            figure;
            plot(theta, cp, 'b-o', 'DisplayName', 'Numerical Cp');
            if ~isempty(cp_analytical)
                plot(theta, cp_analytical, 'r--', 'DisplayName', 'Analytical Cp');
                legend;
            end
            xlabel('Angle (rad)');
            ylabel('C_p');
            title('Pressure Coefficient Comparison');
            grid on;

            % Calculate and display error metrics
            if ~isempty(cp_analytical)
                error = abs(cp - cp_analytical);
                max_error = max(error);
                avg_error = mean(error);
                fprintf('Error Metrics (compared to analytical solution):\n');
                fprintf('Maximum error: %.6f\n', max_error);
                fprintf('Average error: %.6f\n', avg_error);
            end
        end

        % Compute and display lift coefficient
        chord = norm(points(1,:) - points(end-1,:));  % Approximate chord length
        Cl = compute_cl(Vinf, gamma, panel_lengths, chord);
        Cl_analytical = 2*pi*deg2rad(alpha_deg);  % Thin airfoil theory

        fprintf('Lift coefficient Cl = %.4f\n', Cl);
        if ~isempty(Cl_analytical)
            fprintf('Analytical Cl = %.4f\n', Cl_analytical);
            rel_error = abs(Cl - Cl_analytical)/abs(Cl_analytical);
            fprintf('Relative error: %.4f%%\n', rel_error*100);
        end

        % Perform accuracy check
        perform_accuracy_check();

    catch ME
        % Handle errors gracefully
        fprintf(2, 'Error: %s\n', ME.message);
        if exist('filename', 'var')
            fprintf(2, 'Failed to process file: %s\n', filename);
        end
        return;
    end
end

function [panels, points] = read_panels(filename)
    % Read panel data from file with error handling

    try
        % Check if file exists
        if ~exist(filename, 'file')
            error('File %s not found', filename);
        end

        % Read points from file
        points = dlmread(filename);

        % Validate data format
        if size(points, 2) ~= 2
            error('File must contain exactly two columns (x, y)');
        end

        if size(points, 1) < 3
            error('At least 3 points are required to form panels');
        end

        % Check if points form a closed geometry
        if ~isequal(points(1,:), points(end,:))
            warning('The geometry is not closed. Adding connection from last to first point.');
        end

        % Create panels from points
        n = size(points, 1);
        panels = zeros(n, 4);
        for i = 1:n
            x1 = points(i, 1);
            y1 = points(i, 2);
            x2 = points(mod(i, n) + 1, 1);
            y2 = points(mod(i, n) + 1, 2);
            panels(i, :) = [x1 y1 x2 y2];
        end
    catch
        error('Failed to read panel data from file: %s', filename);
    end
end

function [midpoints, normals, panel_lengths, tangents] = compute_control_points(panels)
    % Compute control points, normals, and tangents

    n = size(panels, 1);
    midpoints = zeros(n, 2);
    normals = zeros(n, 2);
    panel_lengths = zeros(n, 1);
    tangents = zeros(n, 2);

    for j = 1:n
        x_a = panels(j, 1);
        y_a = panels(j, 2);
        x_b = panels(j, 3);
        y_b = panels(j, 4);

        % Midpoint
        xm = (x_a + x_b) / 2;
        ym = (y_a + y_b) / 2;
        midpoints(j, :) = [xm ym];

        % Panel length
        dx = x_b - x_a;
        dy = y_b - y_a;
        L = sqrt(dx^2 + dy^2);
        panel_lengths(j) = L;

        % Tangent vector
        tx = dx / L;
        ty = dy / L;
        tangents(j, :) = [tx ty];

        % Normal vector (pointing outward)
        nx = dy / L;
        ny = -dx / L;
        normals(j, :) = [nx ny];
    end
end

function A = compute_influence_matrix(midpoints, normals, panels, panel_lengths)
    % Build influence matrix with source and vortex contributions

    n = size(panels, 1);
    A = zeros(n + 1);

    % 3-point Gauss quadrature points and weights
    gauss_points = [-sqrt(3/5), 5/9; 0, 8/9; sqrt(3/5), 5/9];

    for i = 1:n
        x_i = midpoints(i, 1);
        y_i = midpoints(i, 2);
        nx_i = normals(i, 1);
        ny_i = normals(i, 2);

        for j = 1:n
            x_a_j = panels(j, 1);
            y_a_j = panels(j, 2);
            x_b_j = panels(j, 3);
            y_b_j = panels(j, 4);
            L_j = panel_lengths(j);

            sum_source = 0;
            sum_vortex = 0;

            for k = 1:size(gauss_points, 1)
                s = gauss_points(k, 1);
                w = gauss_points(k, 2);

                % Position on panel j
                x_jk = x_a_j + (x_b_j - x_a_j) * (s + 1) / 2;
                y_jk = y_a_j + (y_b_j - y_a_j) * (s + 1) / 2;

                % Distance from control point i to current point on panel j
                dx = x_i - x_jk;
                dy = y_i - y_jk;
                dist_sq = dx^2 + dy^2;

                if dist_sq < 1e-12
                    continue;
                end

                % Source influence
                dot_product_source = dx * nx_i + dy * ny_i;
                contrib_source = dot_product_source / dist_sq * w;
                sum_source = sum_source + contrib_source;

                % Vortex influence
                dot_product_vortex = -dy * nx_i + dx * ny_i;
                contrib_vortex = dot_product_vortex / dist_sq * w;
                sum_vortex = sum_vortex + contrib_vortex;
            end

            integral_source = sum_source * (L_j / 2);
            integral_vortex = sum_vortex * (L_j / 2);

            A(i, j) = integral_source / (2 * pi);
            A(i, n+1) = A(i, n+1) + integral_vortex / (2 * pi);
        end
    end

    % Kutta condition: γ₁ + γₙ = 0
    A(n+1, 1) = 1;
    A(n+1, n) = 1;
    A(n+1, n+1) = 0;  % γ₁ + γₙ = 0
end

function rhs = compute_rhs(alpha_deg, Vinf, normals)
    % Compute right-hand side of the system

    alpha_rad = deg2rad(alpha_deg);
    n = size(normals, 1);
    rhs = zeros(n + 1, 1);

    for i = 1:n
        nx = normals(i, 1);
        ny = normals(i, 2);
        Vn = Vinf * (cos(alpha_rad) * nx + sin(alpha_rad) * ny);
        rhs(i) = -Vn;
    end
end

function [cp, theta, cp_analytical] = compute_pressure_coefficients(...
    Vinf, alpha_deg, sigma, gamma, panels, midpoints, normals, tangents, panel_lengths)
    % Compute pressure coefficients at each panel

    n = size(panels, 1);
    cp = zeros(n, 1);

    % Try to compute angles for analytical solution (circular cylinder)
    try
        theta = atan2(midpoints(:,2), midpoints(:,1));
        cp_analytical = 1.0 - 4.0 * sin(theta).^2;
    catch
        theta = [];
        cp_analytical = [];
    end

    alpha_rad = deg2rad(alpha_deg);
    u_fs = Vinf * cos(alpha_rad);
    v_fs = Vinf * sin(alpha_rad);

    % 3-point Gauss quadrature points and weights
    gauss_points = [-sqrt(3/5), 5/9; 0, 8/9; sqrt(3/5), 5/9];

    for i = 1:n
        x_i = midpoints(i, 1);
        y_i = midpoints(i, 2);
        tx = tangents(i, 1);
        ty = tangents(i, 2);

        u_ind = 0;
        v_ind = 0;

        for j = 1:n
            x_a_j = panels(j, 1);
            y_a_j = panels(j, 2);
            x_b_j = panels(j, 3);
            y_b_j = panels(j, 4);
            L_j = panel_lengths(j);
            sigma_j = sigma(j);

            % Source contributions
            for k = 1:size(gauss_points, 1)
                s = gauss_points(k, 1);
                w = gauss_points(k, 2);

                % Position on panel j
                x_jk = x_a_j + (x_b_j - x_a_j) * (s + 1) / 2;
                y_jk = y_a_j + (y_b_j - y_a_j) * (s + 1) / 2;

                % Distance from point i to current point on panel j
                dx = x_i - x_jk;
                dy = y_i - y_jk;
                dist_sq = dx^2 + dy^2;

                if dist_sq < 1e-12
                    continue;
                end

                factor = sigma_j * w * (L_j / 2) / (2 * pi * dist_sq);
                u_ind = u_ind + dx * factor;
                v_ind = v_ind + dy * factor;
            end

            % Vortex contributions
            for k = 1:size(gauss_points, 1)
                s = gauss_points(k, 1);
                w = gauss_points(k, 2);

                % Position on panel j
                x_jk = x_a_j + (x_b_j - x_a_j) * (s + 1) / 2;
                y_jk = y_a_j + (y_b_j - y_a_j) * (s + 1) / 2;

                % Distance from point i to current point on panel j
                dx = x_i - x_jk;
                dy = y_i - y_jk;
                dist_sq = dx^2 + dy^2;

                if dist_sq < 1e-12
                    continue;
                end

                factor = gamma * w * (L_j / 2) / (2 * pi * dist_sq);
                u_ind = u_ind - dy * factor;
                v_ind = v_ind + dx * factor;
            end
        end

        % Total velocity components
        u_total = u_ind + u_fs;
        v_total = v_ind + v_fs;

        % Tangential velocity
        Vt = u_total * tx + v_total * ty;

        % Pressure coefficient
        cp(i) = 1.0 - (Vt / Vinf)^2;
    end
end

function Cl = compute_cl(Vinf, gamma, panel_lengths, chord)
    % Compute lift coefficient using Kutta-Joukowski theorem

    Gamma = gamma * sum(panel_lengths);
    Cl = (2 * Gamma) / (Vinf * chord);
end

