                s = [-sqrt(3/5), 0, sqrt(3/5)];
                w = [5/9, 8/9, 5/9];
                x_jk = x_a_j + (x_b_j - x_a_j)*(s(k) + 1)/2;
                y_jk = y_a_j + (y_b_j - y_a_j)*(s(k) + 1)/2;
                dx = x_i - x_jk; dy = y_i - y_jk;
                dist_sq = dx^2 + dy^2;
                if dist_sq < 1e-12, continue; end
                factor = gamma * w(k) * (L_j / 2) / (2 * pi * dist_sq);
                u_ind = u_ind - dy * factor;
                v_ind = v_ind + dx * factor;
            end
        end

        u_total = u_ind + u_fs;
        v_total = v_ind + v_fs;
        Vt = u_total * tx + v_total * ty;
        cp(i) = 1.0 - (Vt / Vinf)^2;
    end
end

function [Cl, Cl_analytical] = compute_cl(Vinf, gamma, panel_lengths, chord, alpha_deg)
    Gamma = gamma * sum(panel_lengths);
    Cl = (2 * Gamma) / (Vinf * chord);
    Cl_analytical = 2 * pi * deg2rad(alpha_deg);
end

