        fprintf('Cp Error (Numerical vs Experimental):\n');
        fprintf('Max error: %.6f | Avg error: %.6f | RMS error: %.6f\n', ...
            max_error_exp, avg_error_exp, rms_error_exp);

        if ~isempty(cp_analytical)
            error_analytical_exp = abs(cp_analytical - cp_exp);
            max_error_ae = max(error_analytical_exp);
            avg_error_ae = mean(error_analytical_exp);
            rms_error_ae = sqrt(mean(error_analytical_exp.^2));
