function report_cl_results(Cl, Cl_analytical, cl_exp)
    fprintf('Lift coefficient C_l = %.4f\n', Cl);
    if ~isempty(Cl_analytical)
        fprintf('Analytical C_l = %.4f\n', Cl_analytical);
        if ~isempty(cl_exp)
            rel_error_analytical = abs(Cl_analytical - cl_exp) / abs(cl_exp);
            rel_error_numerical = abs(Cl - cl_exp) / abs(cl_exp);
            fprintf('Relative error (Numerical vs Exp): %.4f%%\n', rel_error_numerical * 100);
            fprintf('Relative error (Analytical vs Exp): %.4f%%\n', rel_error_analytical * 100);
        else
            rel_error = abs(Cl - Cl_analytical) / abs(Cl_analytical);
            fprintf('Relative error (Numerical vs Analytical): %.4f%%\n', rel_error * 100);
        end
    end
end

function perform_accuracy_check()
