        [panels, ~] = read_panels(temp_filename);
        Vinf = 1.0; alpha_deg = 0.0;
        [midpoints, normals, panel_lengths, ~] = compute_control_points(panels);
        A = compute_influence_matrix(midpoints, normals, panels, panel_lengths);
        rhs = compute_rhs(alpha_deg, Vinf, normals);
        solution = A \ rhs;
        sigma = solution(1:n_panels); gamma = solution(n_panels + 1);
        [cp, ~, cp_analytical] = compute_pressure_coefficients(Vinf, alpha_deg, ...
            sigma, gamma, panels, midpoints, normals, [], panel_lengths);
        if ~isempty(cp_analytical)
