#include <iostream>
#include <vector>
#include <memory>
#include <stdexcept>
#include <cmath>
#include <algorithm>
#include <unordered_map>
#include <limits>
#include <chrono>
#include <omp.h>  // For OpenMP parallelization

// Forward declaration
class Neuron;

// Synapse structure to hold connection information
struct Synapse {
    std::weak_ptr<Neuron> neuron;  // Weak pointer to avoid circular references
    double weight;                 // Synaptic weight
    double last_spike;             // Time of last spike from this synapse

    Synapse(std::shared_ptr<Neuron> n, double w) 
        : neuron(n), weight(w), last_spike(-1e9) {}
};

class Neuron {
private:
    // Izhikevich model parameters
    double a_, b_, c_, d_;
    double threshold_;

    // Neuron state variables
    double v_;  // Membrane potential
    double u_;  // Recovery variable

    // Spike-related variables
    bool spike_;
    double last_spike_time_;

    // Connections
    std::vector<Synapse> incoming_;
    std::vector<Synapse> outgoing_;

    // Time tracking
    double current_time_;

    // Synaptic plasticity parameters
    double tau_stdp_;  // Time constant for STDP (20ms typical)
    double max_weight_;
    double min_weight_;

public:
    // Constructor with validation
    Neuron(double a, double b, double c, double d, double threshold = 30.0)
        : a_(a), b_(b), c_(c), d_(d), threshold_(threshold),
          v_(-70.0), u_(b * v_), 
          spike_(false), last_spike_time_(-1e9),
          current_time_(0.0),
          tau_stdp_(20.0), max_weight_(2.0), min_weight_(0.1) {

        // Validate parameters
        if (a <= 0 || b <= 0 || c <= 0 || d <= 0) {
            throw std::invalid_argument("Izhikevich parameters a, b, c, d must be positive");
        }
        if (threshold <= c) {
            throw std::invalid_argument("Threshold must be greater than reset potential c");
        }
    }

    // Connect a pre-synaptic neuron to this neuron as input
    void connect_input(std::shared_ptr<Neuron> pre_neuron, double weight = 1.0) {
        if (!pre_neuron) {
            throw std::invalid_argument("Cannot connect null neuron as input");
        }
        if (weight < min_weight_ || weight > max_weight_) {
            throw std::invalid_argument("Weight must be between " + 
                std::to_string(min_weight_) + " and " + std::to_string(max_weight_));
        }

        incoming_.emplace_back(pre_neuron, weight);
    }

    // Connect this neuron to a post-synaptic neuron as output
    void connect_output(std::shared_ptr<Neuron> post_neuron, double weight = 1.0) {
        if (!post_neuron) {
            throw std::invalid_argument("Cannot connect null neuron as output");
        }
        if (weight < min_weight_ || weight > max_weight_) {
            throw std::invalid_argument("Weight must be between " + 
                std::to_string(min_weight_) + " and " + std::to_string(max_weight_));
        }

        outgoing_.emplace_back(post_neuron, weight);
    }

    // Disconnect a pre-synaptic neuron from this neuron
    bool disconnect_input(std::shared_ptr<Neuron> pre_neuron) {
        auto it = std::remove_if(incoming_.begin(), incoming_.end(), 
            [&](const Synapse& synapse) {
                auto locked = synapse.neuron.lock();
                return locked && locked.get() == pre_neuron.get();
            });

        if (it != incoming_.end()) {
            incoming_.erase(it, incoming_.end());
            return true;
        }
        return false;
    }

    // Disconnect a post-synaptic neuron from this neuron
    bool disconnect_output(std::shared_ptr<Neuron> post_neuron) {
        auto it = std::remove_if(outgoing_.begin(), outgoing_.end(), 
            [&](const Synapse& synapse) {
                auto locked = synapse.neuron.lock();
                return locked && locked.get() == post_neuron.get();
            });

        if (it != outgoing_.end()) {
            outgoing_.erase(it, outgoing_.end());
            return true;
        }
        return false;
    }

    // Update neuron state using Euler integration
    bool step(double dt, double external_input = 0.0) {
        if (dt <= 0) {
            throw std::invalid_argument("Time step must be positive");
        }

        spike_ = false;

        // Integrate differential equations
        double dv = (0.04 * v_ * v_ + 5 * v_ + 140 - u_ + external_input) * dt;
        double du = (a_ * (b_ * v_ - u_)) * dt;
        v_ += dv;
        u_ += du;

        // Check for spike
        if (v_ >= threshold_) {
            spike_ = true;
            last_spike_time_ = current_time_;
            // Reset membrane potential
            v_ = c_;
            u_ += d_;
            return true;
        }
        return false;
    }

    // Update the neuron's state and process incoming spikes
    double update(double dt, double external_input = 0.0) {
        // First, process incoming spikes
        double input_current = process_inputs(dt);

        // Then update neuron state
        bool spiked = step(dt, external_input + input_current);

        // Finally, propagate spikes to connected neurons
        if (spike_) {
            propagate_spike();
        }

        // Update time tracking
        current_time_ += dt;

        return input_current;
    }

private:
    // Process incoming spikes and update synaptic weights
    double process_inputs(double dt) {
        if (dt <= 0) {
            throw std::invalid_argument("Time step must be positive");
        }

        double total_input = 0.0;

        // Parallelize synapse processing with OpenMP
        #pragma omp parallel for reduction(+:total_input)
        for (size_t i = 0; i < incoming_.size(); ++i) {
            Synapse& synapse = incoming_[i];
            auto pre = synapse.neuron.lock();
            if (!pre) continue;  // Skip if neuron destroyed

            // Check if presynaptic neuron spiked recently
            if (pre->has_spiked_recently(current_time_)) {
                // Apply synaptic plasticity
                apply_plasticity(synapse);

                // Add current to this neuron proportional to weight
                #pragma omp atomic
                total_input += synapse.weight;
            }

            // Update spike timer
            if (synapse.last_spike > -1e9) {
                synapse.last_spike -= dt;
            }
        }

        return total_input;
    }

    // Apply STDP plasticity rule to a synapse
    void apply_plasticity(Synapse& synapse) {
        auto pre = synapse.neuron.lock();
        if (!pre) return;

        double delta_t = last_spike_time_ - pre->last_spike_time_;

        // STDP rule: pre before post -> potentiation, post before pre -> depression
        if (delta_t > 0 && delta_t < tau_stdp_) {
            // Long-Term Potentiation (LTP)
            // Weight update with bounded growth
            synapse.weight += 0.1 * (1.0 - synapse.weight);
            if (synapse.weight > max_weight_) {
                synapse.weight = max_weight_;
            }
        } else if (delta_t < 0 && delta_t > -tau_stdp_) {
            // Long-Term Depression (LTD)
            // Weight update with bounded decay
            synapse.weight -= 0.1 * synapse.weight;
            if (synapse.weight < min_weight_) {
                synapse.weight = min_weight_;
            }
        }
    }

    // Check if the neuron spiked in the current time step
    bool has_spiked_recently(double current_time) const {
        // Consider a spike if it happened in the current time step
        return (current_time - last_spike_time_) < 1e-9;
    }

    // Propagate spikes to connected post-synaptic neurons
    void propagate_spike() {
        for (auto& synapse : outgoing_) {
            auto post = synapse.neuron.lock();
            if (post) {
                post->update_input_connection(this, synapse.weight);
            }
        }
    }

    // Called by presynaptic neurons when they spike
    void update_input_connection(Neuron* pre, double weight) {
        // Find the synapse from this neuron to the specified presynaptic neuron
        for (auto& synapse : incoming_) {
            auto locked = synapse.neuron.lock();
            if (locked && locked.get() == pre) {
                synapse.last_spike = current_time_;
                // Apply synaptic plasticity
                apply_plasticity(synapse);
                break;
            }
        }
    }

public:
    // Getters for state variables
    double get_voltage() const { return v_; }
    double get_recovery() const { return u_; }
    bool has_spiked() const { return spike_; }
    double get_last_spike_time() const { return last_spike_time_; }
    size_t get_incoming_count() const { return incoming_.size(); }
    size_t get_outgoing_count() const { return outgoing_.size(); }

    // Biological Relevance of STDP:
    // -------------------------------
    // The Spike Timing Dependent Plasticity (STDP) mechanism implemented here
    // is a fundamental biological learning rule that governs synaptic strength
    // based on the relative timing of pre- and post-synaptic spikes:
    //
    // 1. Long-Term Potentiation (LTP):
    //    When a pre-synaptic neuron fires just before a post-synaptic neuron
    //    (within the tau_stdp window), the synapse is strengthened. This
    //    reflects Hebbian learning ("cells that fire together, wire together").
    //
    // 2. Long-Term Depression (LTD):
    //    When a post-synaptic neuron fires before a pre-synaptic neuron,
    //    the synapse is weakened. This helps eliminate unnecessary connections.
    //
    // 3. Biological Significance:
    //    - Critical for sensory processing and memory formation
    //    - Enables temporal coding of information
    //    - Supports network self-organization and refinement
    //    - Maintains homeostasis in neural circuits
    //
    // This mechanism allows the network to adapt to temporal patterns in input,
    // making it suitable for modeling learning and adaptation in primitive animals.
};

// Network class to manage a collection of neurons
class NeuralNetwork {
private:
    std::vector<std::shared_ptr<Neuron>> neurons_;
    std::unordered_map<int, std::shared_ptr<Neuron>> neuron_map_;
    double dt_;  // Time step for the simulation

public:
    NeuralNetwork(double dt) : dt_(dt) {
        if (dt <= 0) {
            throw std::invalid_argument("Time step must be positive");
        }
        // Enable OpenMP parallelism
        omp_set_num_threads(omp_get_max_threads());
    }

    // Add a neuron to the network
    int add_neuron(std::shared_ptr<Neuron> neuron) {
        if (!neuron) {
            throw std::invalid_argument("Cannot add null neuron to network");
        }

        neurons_.push_back(neuron);
        int id = neurons_.size() - 1;
        neuron_map_[id] = neuron;
        return id;
    }

    // Connect two neurons in the network
    bool connect_neurons(int pre_id, int post_id, double weight = 1.0, double reciprocal_weight = 0.0) {
        auto pre_it = neuron_map_.find(pre_id);
        auto post_it = neuron_map_.find(post_id);

        if (pre_it == neuron_map_.end() || post_it == neuron_map_.end()) {
            return false;
        }

        // Connect the neurons
        pre_it->second->connect_output(post_it->second, weight);
        post_it->second->connect_input(pre_it->second, weight);

        // If reciprocal weight is specified, create a reciprocal connection
        if (reciprocal_weight > 0) {
            post_it->second->connect_output(pre_it->second, reciprocal_weight);
            pre_it->second->connect_input(post_it->second, reciprocal_weight);
        }

        return true;
    }

    // Disconnect two neurons in the network
    bool disconnect_neurons(int pre_id, int post_id) {
        auto pre_it = neuron_map_.find(pre_id);
        auto post_it = neuron_map_.find(post_id);

        if (pre_it == neuron_map_.end() || post_it == neuron_map_.end()) {
            return false;
        }

        // Disconnect the neurons
        bool input_disconnected = post_it->second->disconnect_input(pre_it->second);
        bool output_disconnected = pre_it->second->disconnect_output(post_it->second);

        return input_disconnected && output_disconnected;
    }

    // Run the simulation for a specified duration
    void run_simulation(double duration, double external_input = 0.0) {
        if (duration <= 0) {
            throw std::invalid_argument("Simulation duration must be positive");
        }

        int steps = static_cast<int>(duration / dt_);
        std::vector<double> inputs(neurons_.size(), external_input);

        // Progress tracking
        auto start_time = std::chrono::high_resolution_clock::now();
        int progress_interval = std::max(1, steps / 20);

        for (int i = 0; i < steps; ++i) {
            // Parallelize neuron updates with OpenMP
            #pragma omp parallel for
            for (size_t n = 0; n < neurons_.size(); ++n) {
                neurons_[n]->update(dt_, inputs[n]);
            }

            // Progress output
            if (i % progress_interval == 0) {
                std::cout << "Simulation progress: " << (i * 100.0 / steps) << "% complete\r" << std::flush;
            }
        }

        auto end_time = std::chrono::high_resolution_clock::now();
        std::chrono::duration<double> elapsed = end_time - start_time;
        std::cout << "\nSimulation completed in " << elapsed.count() << " seconds" << std::endl;
    }

    // Get neuron by ID
    std::shared_ptr<Neuron> get_neuron(int id) const {
        auto it = neuron_map_.find(id);
        return (it != neuron_map_.end()) ? it->second : nullptr;
    }

    // Get number of neurons in the network
    size_t size() const { return neurons_.size(); }
};

// Example usage
int main() {
    try {
        // Create a neural network with time step of 0.01 ms
        NeuralNetwork network(0.01);

        // Create two neurons with typical Izhikevich parameters
        auto n1 = std::make_shared<Neuron>(0.02, 0.2, -65, 8);
        auto n2 = std::make_shared<Neuron>(0.02, 0.2, -65, 8);

        // Add neurons to the network
        int id1 = network.add_neuron(n1);
        int id2 = network.add_neuron(n2);

        // Connect the neurons
        network.connect_neurons(id1, id2, 1.5);

        // Run simulation for 1000 ms
        network.run_simulation(1000, 10);

        // Output some results
        std::cout << "Neuron 1 voltage: " << n1->get_voltage() << std::endl;
        std::cout << "Neuron 2 voltage: " << n2->get_voltage() << std::endl;

    } catch (const std::exception& e) {
        std::cerr << "Error: " << e.what() << std::endl;
        return 1;
    }

    return 0;
