% Custom probable prime check (Miller-Rabin)
function result = is_probable_prime(n, rounds)
    if n.compareTo(BigInteger('2')) < 0
        result = false;
        return;
    end
    if mod(n, BigInteger('2')) == 0
        result = (n.compareTo(BigInteger('2')) == 0);
        return;
    end

    % Write n-1 as d*2^s
    d = n.subtract(BigInteger('1'));
    s = 0;
    while mod(d, BigInteger('2')) == 0
        d = d.divide(BigInteger('2'));
        s = s + 1;
    end

    result = true;
    for i = 1:rounds
        a = BigInteger.valueOf(randi([2, 100]));
        x = a.modPow(d, n);
        if x.compareTo(BigInteger('1')) == 0 || x.compareTo(n.subtract(BigInteger('1'))) == 0
            continue;
        end

        witnessLoop = true;
        for r = 1:s-1
            x = x.modPow(BigInteger('2'), n);
            if x.compareTo(n.subtract(BigInteger('1'))) == 0
                witnessLoop = false;
                break;
            end
        end
        if witnessLoop
            result = false;
            return;
        end
    end
end

% Step 2: Generate 1024-bit primes for RSA-2048 equivalent security
p = generate_large_prime(1024);
q = generate_large_prime(1024);
while p.compareTo(q) == 0  % Ensure distinct primes
    q = generate_large_prime(1024);
end

% Step 3: Compute modulus n = p * q
n = p.multiply(q);

% Step 4: Compute Euler's totient phi(n) = (p-1)*(q-1)
phi = p.subtract(BigInteger('1')).multiply(q.subtract(BigInteger('1')));

% Step 5: Choose public exponent e (commonly 65537)
e = BigInteger('65537');
while gcd(e, phi).compareTo(BigInteger('1')) ~= 0
    e = e.add(BigInteger('2'));  % Increment by 2 to maintain oddness
end

% Step 6: Compute private exponent d = e^-1 mod phi
% Using Java's BigInteger.modInverse()
d = e.modInverse(phi);

% Display keys
fprintf('Public Key (e, n):\n');
fprintf('e = %s\n', char(e.toString()));
fprintf('n = %s\n', char(n.toString()));
fprintf('\nPrivate Key (d, n):\n');
fprintf('d = %s\n', char(d.toString()));

