## 🧩 Backend: Python API (Flask Example)

```python
# backend.py
from flask import Flask, request, jsonify
from werkzeug.utils import secure_filename
import PyPDF2
import docx
import re
import requests
from bs4 import BeautifulSoup
import random

app = Flask(__name__)

def extract_text_from_file(file):
    """Extracts text from uploaded file (PDF, DOCX, or TXT)."""
    filename = secure_filename(file.filename)
    if filename.endswith('.txt'):
        return file.read().decode('utf-8')
    elif filename.endswith('.pdf'):
        reader = PyPDF2.PdfReader(file)
        return ' '.join(page.extract_text() for page in reader.pages)
    elif filename.endswith('.docx'):
        doc = docx.Document(file)
        return ' '.join(paragraph.text for paragraph in doc.paragraphs)
    else:
        raise ValueError("Unsupported file type")

def extract_ingredients(recipe_text):
    """Simple regex-based ingredient extractor."""
    ingredients = []
    lines = recipe_text.split('\n')
    in_ingredients = False
    for line in lines:
        line = line.strip().lower()
        if any(kw in line for kw in ['ingredients', 'ingredient', 'ingr.']):
            in_ingredients = True
            continue
        if not in_ingredients: continue
        if not line or 'instruction' in line: break
        if line:
            ing = re.split(r'[,email protected]#~%^&*()+=\[\]]', line, 1)[0].strip()
            if ing:
                ingredients.append(ing)
    return ingredients

def fetch_magical_property(ingredient):
    """Fetches magical properties from the web (e.g., witchipedia.com or similar)."""
    try:
        search_query = f"magical properties of {ingredient} site:witchipedia.com"
        url = f"https://www.google.com/search?q={search_query}"
        headers = {"User-Agent": "Mozilla/5.0"}
        res = requests.get(url, headers=headers)
        soup = BeautifulSoup(res.text, 'html.parser')
        link = soup.find('a', href=True)
        if link:
            article_url = link['href']
            if article_url.startswith("/url?q="):
                article_url = article_url[7:].split('&')[0]
            res = requests.get(article_url, headers=headers)
            soup = BeautifulSoup(res.text, 'html.parser')
            # Simplified: extract first few paragraphs as magical effects
            paras = soup.find_all('p')[:3]
            effects = [p.get_text(strip=True) for p in paras if p.get_text(strip=True)]
            return effects
    except Exception as e:
        print(f"Error fetching for {ingredient}: {e}")
        return [f"Unknown magical properties for {ingredient}"]
    return [f"Unknown magical properties for {ingredient}"]

def generate_spell(ingredients):
    """Generates a spell from magical effects."""
    all_effects = []
    for ing in ingredients:
        effects = fetch_magical_property(ing)
        for effect in effects:
            all_effects.append({"ingredient": ing, "effect": effect})

    if not all_effects:
        return "No magical effects found in any ingredients."

    spell = []
    spell.append("=== Magical Recipe Spell ===\n")
    spell.append("By the power of these sacred ingredients, let the magic unfold.\n")
    for effect in random.sample(all_effects, min(5, len(all_effects))):
        spell.append(f"Let the essence of {effect['ingredient']} {effect['effect']},")
    spell.append("\nSo it is written, so it shall be.")
    return "\n".join(spell)

@app.route('/generate-spell', methods=['POST'])
def generate_spell_route():
    if 'file' not in request.files:
        return jsonify({"error": "No file uploaded"}), 400
    file = request.files['file']
    if file.filename == '':
        return jsonify({"error": "Empty filename"}), 400

    try:
        recipe_text = extract_text_from_file(file)
        ingredients = extract_ingredients(recipe_text)
        spell = generate_spell(ingredients)
        return jsonify({"spell": spell, "ingredients": ingredients})
    except Exception as e:
        return jsonify({"error": str(e)}), 500

if __name__ == '__main__':
    app.run(debug=True)
```

