```javascript
const svg = d3.select("svg");
const width = +svg.attr("width");
const height = +svg.attr("height");

// Center the solar system
const centerX = width / 2;
const centerY = height / 2;

// Scale for AU to pixels
const scale = d3.scaleLinear()
  .domain([0, 6])  // Max orbital radius in AU (e.g., Jupiter)
  .range([0, 300]);  // Max pixels from center

// Load JSON data from Python-generated file
d3.json("planets.json").then(data => {
  const planets = data.planets;

  // Draw the Sun
  svg.append("circle")
    .attr("cx", centerX)
    .attr("cy", centerY)
    .attr("r", 10)
    .attr("fill", "yellow");

  // Draw planets
  const planetCircles = svg.selectAll("planet")
    .data(planets)
    .enter()
    .append("circle")
    .attr("r", 5)
    .attr("fill", d => d.color);

  // Function to update positions
  function update(timeDays) {
    planets.forEach(p => {
      const x = p.position.x / 1e6; // Convert km to AU-like unit
      const y = p.position.y / 1e6;
      const px = centerX + scale(x);
      const py = centerY + scale(y);
      svg.select(`[data-name='${p.name}']`).attr("cx", px).attr("cy", py);
    });
  }

  update(0); // Initial positions
});
```

