### `app3d.js`
```javascript
let scene, camera, renderer;
let planets = [];

init();
animate();

function init() {
  scene = new THREE.Scene();

  camera = new THREE.PerspectiveCamera(75, window.innerWidth / window.innerHeight, 0.1, 1000);
  camera.position.z = 50;

  renderer = new THREE.WebGLRenderer({ antialias: true });
  renderer.setSize(window.innerWidth, window.innerHeight);
  document.body.appendChild(renderer.domElement);

  // Light
  const light = new THREE.PointLight(0xffffff, 1.5);
  light.position.set(0, 0, 0);
  scene.add(light);

  // Sun
  const sunGeometry = new THREE.SphereGeometry(2, 32, 32);
  const sunMaterial = new THREE.MeshBasicMaterial({ color: 0xFFFF00 });
  const sun = new THREE.Mesh(sunGeometry, sunMaterial);
  scene.add(sun);

  // Load JSON data
  fetch('planets.json')
    .then(res => res.json())
    .then(data => {
      data.planets.forEach(p => {
        const geometry = new THREE.SphereGeometry(0.5, 16, 16);
        const material = new THREE.MeshBasicMaterial({ color: p.color });
        const mesh = new THREE.Mesh(geometry, material);
        scene.add(mesh);
        planets.push({ mesh, data: p });
      });
    });

  window.addEventListener('resize', onWindowResize, false);
}

function onWindowResize() {
  camera.aspect = window.innerWidth / window.innerHeight;
  camera.updateProjectionMatrix();
  renderer.setSize(window.innerWidth, window.innerHeight);
}

function animate(time) {
  requestAnimationFrame(animate);

  // Update planet positions based on time
  const timeDays = (time / 1000) * 10; // Fast forward
  planets.forEach(obj => {
    const p = obj.data;
    const angle = (2 * Math.PI / p.period) * timeDays;
    const x = p.radius * Math.cos(angle);
    const y = p.radius * Math.sin(angle);
    obj.mesh.position.set(x * 5, y * 5, 0); // Scale factor for visibility
  });

  renderer.render(scene, camera);
}
```

> 🌠 Tip: You can enhance this by loading planet textures using `THREE.TextureLoader`.

